package trackerweb

const projectStatsTemplate = `{{define "project-stats"}}<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="refresh" content="1"><title>{{.Project.ID}} stats · SavewebHQ</title><link rel="stylesheet" href="/assets/admin.css"></head><body><header><a class="brand" href="/admin">SavewebHQ</a><div class="account"><span>{{.User.GitHubLogin}}</span></div></header><main><div class="breadcrumbs"><a href="/admin">Projects</a><span>/</span><a href="/admin/projects/{{.Project.ID}}"><code>{{.Project.ID}}</code></a><span>/</span><span>Stats</span></div><div class="page-title"><div><h1>{{.Project.ID}} stats</h1><p>Process-local rolling windows · refreshes every second</p></div></div><section class="metrics"><div><span>Claim QPS · 10s</span><strong>{{printf "%.2f" .ClaimQPS10}}</strong></div><div><span>Completed QPS · 10s</span><strong>{{printf "%.2f" .CompletedQPS10}}</strong></div><div><span>Claim QPS · 60s</span><strong>{{printf "%.2f" .ClaimQPS60}}</strong></div><div><span>Completed QPS · 60s</span><strong>{{printf "%.2f" .CompletedQPS60}}</strong></div></section></main></body></html>{{end}}`
